]

def num_border_sides(grid, color):
    h, w = len(grid), len(grid[0])
    touches = {'top': False, 'bottom': False, 'left': False, 'right': False}

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color:
                if r == 0:
                    touches['top'] = True
                if r == h - 1:
                    touches['bottom'] = True
                if c == 0:
                    touches['left'] = True
                if c == w - 1:
                    touches['right'] = True

    return sum(touches.values())

print("Test input border analysis (bg=7):")
non_bg_test = sorted(set(v for row in demo_test_input for v in row) - {7})
for c in non_bg_test:
    nsides = num_border_sides(demo_test_input, c)
    print(f"Color {c}: touches {nsides} sides")

